Matrix x = Matrix.fromRows(new double[][]{{0, 0}, {0, 1}, {1, 0}, {1, 1}, {2, 2}, {2, 1}});
double[] y = {0, 0, 1, 1, 1, 1};
DataSplit.Holdout split = DataSplit.holdout(x, y, 0.25, 42L);
LinearRegression model = LinearRegression.builder().build()
        .fit(split.trainFeatures(), split.trainTargets());
double[] predicted = model.predict(split.testFeatures());

double[] a = {1.0, 2.0, 3.0};
double[] b = {1.0, 4.0, 3.0};
double euclidean = DistanceMetric.EUCLIDEAN.distance(a, 0, b, 0, 3);
double manhattan = DistanceMetric.MANHATTAN.distance(a, 0, b, 0, 3);

Matrix x = Matrix.fromRows(new double[][]{{0, 0}, {0, 1}, {1, 0}, {1, 1}});
double[] y = {0, 1, 1, 0};
Estimator model = KNearestNeighbors.builder().k(3).build().fit(x, y);
double[] prediction = model.predict(x);

Matrix x = Matrix.fromRows(new double[][]{{0, 0}, {0, 1}, {1, 0}, {1, 1}, {2, 2}, {2, 1}});
double[] y = {0.5, 1.0, 1.5, 2.0, 2.5, 2.2};
Estimator model = JSL.fit(JSL.Algorithm.RIDGE, x, y);
double[] prediction = JSL.predict(model, x);
double score = JSL.crossValidate(JSL.Algorithm.RIDGE, x, y, 3, JSL.Metric.R2);

Matrix x = Matrix.fromRows(new double[][]{{0, 0}, {0, 1}, {1, 0}, {1, 1}});
double[] y = {0, 1, 1, 0};
KNearestNeighbors knn = KNearestNeighbors.builder()
        .k(3)
        .metric(DistanceMetric.MANHATTAN)
        .build()
        .fit(x, y);
double[] labels = knn.predict(x);

Matrix x = Matrix.fromRows(new double[][]{{0, 0}, {0, 1}, {1, 0}, {1, 1}});
double[] y = {0.0, 1.0, 1.0, 2.0};
KNeighborsRegressor regressor = KNeighborsRegressor.builder().k(2).build().fit(x, y);
double[] predictions = regressor.predict(x);

Matrix x = Matrix.fromRows(new double[][]{{1, 0}, {0, 1}, {1, 1}, {2, 2}});
double[] y = {1.0, 2.0, 3.0, 5.0};
Lasso lasso = Lasso.builder()
        .alpha(0.1)
        .maxIterations(500)
        .build()
        .fit(x, y);
double[] coefficients = lasso.weights();
double bias = lasso.intercept();

Matrix x = Matrix.fromRows(new double[][]{{0, 1}, {1, 1}, {2, 1}, {3, 1}});
double[] y = {1.0, 3.0, 5.0, 7.0};
LinearRegression model = LinearRegression.builder()
        .learningRate(0.05)
        .epochs(2000)
        .fitIntercept(true)
        .build()
        .fit(x, y);
double[] predictions = model.predict(x);
double one = model.predictOne(new double[]{4.0, 1.0}, 0);

Matrix x = Matrix.fromRows(new double[][]{{0, 0}, {0, 1}, {1, 0}, {1, 1}});
double[] y = {0, 0, 1, 1};
LinearSVM svm = LinearSVM.builder()
        .lambda(0.01)
        .epochs(20)
        .seed(42L)
        .build()
        .fit(x, y);
double[] labels = svm.predict(x);
double[] w = svm.weights();
double b = svm.bias();

Matrix x = Matrix.fromRows(new double[][]{{0, 0}, {0, 1}, {1, 0}, {1, 1}});
double[] y = {0, 0, 1, 1};
LogisticRegression model = LogisticRegression.builder()
        .learningRate(0.1)
        .epochs(2000)
        .build()
        .fit(x, y);
double[] probability = model.predictProbability(x);
double[] labels = model.predict(x);

double[] expected = {1, 0, 1, 1, 0};
double[] predicted = {1, 0, 0, 1, 0};
double accuracy = Metrics.accuracy(expected, predicted);
double f1 = Metrics.f1(expected, predicted, 1.0);
int[][] matrix = Metrics.confusionMatrix(expected, predicted);
double auc = Metrics.rocAuc(expected, new double[]{0.9, 0.1, 0.4, 0.8, 0.2});

Matrix x = Matrix.fromRows(new double[][]{{0, 0}, {0, 1}, {1, 0}, {1, 1}});
double[] y = {0.0, 1.0, 1.0, 2.0};
Ridge ridge = Ridge.builder()
        .alpha(0.5)
        .fitIntercept(true)
        .build()
        .fit(x, y);
double[] coefficients = ridge.weights();
double bias = ridge.intercept();
double[] predictions = ridge.predict(x);
